@@ -1146,2 +1146,2 @@
-  // Check for ((x & ((1<<(32-c0))-1)) << c0) which ANDs off high bits
-  // before shifting them away.
+  // Check for (x & mask) << c0 where mask contains all bits that survive
+  // the shift. Any additional bits in mask are shifted away.
@@ -1150,3 +1150,6 @@
-  if (add1_op == Op_And(bt) &&
-      phase->type(add1->in(2)) == TypeInteger::make(bits_mask, bt)) {
-    return LShiftNode::make(add1->in(1), in(2), bt);
+  if (add1_op == Op_And(bt)) {
+    const TypeInteger* mask_t = phase->type(add1->in(2))->is_integer(bt);
+    if (mask_t->is_con() &&
+        (mask_t->get_con_as_long(bt) & bits_mask) == bits_mask) {
+      return LShiftNode::make(add1->in(1), in(2), bt);
+    }

@@ -68,0 +68,1 @@
+            "testLShiftOfMaskedInt",
@@ -126,0 +127,2 @@
+        Asserts.assertEQ((a & 0x7fffffff) << 2,
+                         testLShiftOfMaskedInt(a));
@@ -443,0 +446,7 @@
+    @Test
+    @IR(counts = { IRNode.LSHIFT_I, "1" }, failOn = { IRNode.AND_I })
+    // Checks (x & 0x7fffffff) << 2 => x << 2
+    public int testLShiftOfMaskedInt(int x) {
+        return (x & 0x7fffffff) << 2;
+    }
+

@@ -66,0 +66,1 @@
+            "testLShiftOfMaskedLong",
@@ -122,0 +123,2 @@
+        Asserts.assertEQ((a & 0xfedb871fL) << 63,
+                         testLShiftOfMaskedLong(a));
@@ -364,0 +367,7 @@
+    @Test
+    @IR(counts = { IRNode.LSHIFT_L, "1" }, failOn = { IRNode.AND_L })
+    // Checks (x & 0xfedb871fL) << 63 => x << 63
+    public long testLShiftOfMaskedLong(long x) {
+        return (x & 0xfedb871fL) << 63;
+    }
+
